syntax:
fork();
/* ... error checking ... */
execve("/path/to/cgi_program", args, envp);

code_example:
#include <unistd.h>
#include <stdio.h>
int main() {
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork failed");
        return 1;
    }
    else if (pid == 0) {
        char *args[] = {"/path/to/cgi_program", NULL};
        char *envp[] = {NULL};
        execve("/path/to/cgi_program", args, envp);
        perror("execve failed");
        return 1;
    }
    else {
        printf("Parent process continues...
");
        return 0;
    }
}
